const TOKENMGR_PUBKEY = 'p1jdd5yJKobvK0GUMo9VJA/BSdZtCiLzyVel6yOUjVY='

function b64urlDecode(value) {
    const normalized = String(value || '').replace(/-/g, '+').replace(/_/g, '/');
    const pad = normalized.length % 4;
    const padded = pad ? normalized + '='.repeat(4 - pad) : normalized;
    return Buffer.from(padded, 'base64');
}

function parseTokenPart(part) {
    let jsonText = '';
    try {
        jsonText = b64urlDecode(part).toString('utf8');
        return JSON.parse(jsonText);
    } catch (err) {
        throw new Error('invalid JWT segment: ' + err.message);
    }
}

const defaultPub = 'P9hw69ClmtnxaQFX5Ftaa+nFx1Fj6e5CDYta1Ef4S+0=';
const pubBase64 = (TOKENMGR_PUBKEY || defaultPub).trim();
const pubKey = crypto.createPublicKey({
    key: {
        kty: 'OKP',
        crv: 'Ed25519',
        x: Buffer.from(pubBase64, 'base64').toString('base64url')
    },
    format: 'jwk'
});

let authHeader = '';
// Customized Header
if (msg.headers && msg.headers.Authorization) {
    authHeader = msg.headers.Authorization;
//  Standard Request IN
} else if (msg.req && msg.req.headers && msg.req.headers.authorization) {
    authHeader = msg.req.headers.authorization;
}

if (!/^Bearer\s+/i.test(authHeader)) {
    msg.valid = false;
    msg.statusCode = 401;
    msg.payload = { valid: false, error: 'Missing Bearer authorization header' };
    return msg;
}

const token = authHeader.replace(/^Bearer\s+/i, '').trim();
const parts = token.split('.');

if (parts.length !== 3) {
    msg.valid = false;
    msg.statusCode = 401;
    msg.payload = { valid: false, error: 'Token is not a JWT-shaped value' };
    return msg;
}

try {
    const header = parseTokenPart(parts[0]);
    const claims = parseTokenPart(parts[1]);
    const signingInput = parts[0] + '.' + parts[1];
    const sig = b64urlDecode(parts[2]);

    if (header.alg !== 'EdDSA') {
        throw new Error('Unsupported token alg: ' + header.alg);
    }

    const isValid = crypto.verify(null, Buffer.from(signingInput), pubKey, sig);
    if (!isValid) {
        throw new Error('signature does not match');
    }

    msg.valid = true;
    msg.header = header;
    msg.claims = claims;
    msg.payload = { valid: true, header, claims };
    return msg;
} catch (err) {
    msg.valid = false;
    msg.statusCode = 401;
    msg.payload = { valid: false, error: err.message };
    return msg;
}

const now = Math.floor(Date.now() / 1000);

if (msg.claims && msg.claims.exp !== undefined && Number(msg.claims.exp) <= now) {
    msg.valid = false;
    msg.statusCode = 401;
    msg.payload = { valid: false, error: 'Token has expired' };
    return msg;
}

return msg;
